import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Vente & encaissement","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/03-sales.md","filePath":"generated/modules/03-sales.md","lastUpdated":null}'),n={name:"modules/03-sales.md"};function r(i,a,o,p,l,c){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="vente-encaissement" tabindex="-1">Vente &amp; encaissement <a class="header-anchor" href="#vente-encaissement" aria-label="Permalink to &quot;Vente &amp; encaissement&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1 · <a href="/VendoraSystem-docs/specs/03-sales">spécification complète</a></span></p><p>Flux de vente de la caisse : écran &lt; 100 ms hors ligne, moteur de calcul partagé revérifié par le serveur, paiements espèces / carte / mixtes, fournisseurs de paiement simulés, pourboires, tickets ESC/POS, annulations et retours. Le cœur est fait et prouvé sur Android et iOS ; remises en caisse avec seuils et PIN manager livrées au lot 3.2 ; restent la mise en attente, le reçu digital, les vraies passerelles de paiement et les paiements de phase 3 (ardoise, titre-restaurant).</p><div class="kpis"><div><b>21</b><span>faites</span></div><div><b>10</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>1</b><span>bloquées</span></div></div><h2 id="ecran-de-vente" tabindex="-1">Écran de vente <a class="header-anchor" href="#ecran-de-vente" aria-label="Permalink to &quot;Écran de vente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Écran de vente</strong><br><span class="muted">Recherche, scan, boutons rapides et panier lus dans la base locale, indicateur de synchronisation, vendeur et session en en-tête.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-01, RG-SALE-04, RG-SALE-06</td><td>1.x, UX2, UX3</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux2-caisse-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux2-caisse-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux3-tablette-android">📷</a></td></tr><tr><td><strong>Réponse &lt; 100 ms</strong><br><span class="muted">Chaque action caissier est mesurée (p50 / p95 / max) et la latence des caisses remonte au tableau de bord.<br><i>Recherche Android in-app à re-mesurer sur appareil au repos / milieu de gamme ; « cafe » au clavier à vérifier sur iOS.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-01</td><td>1.x, 2.21, 2.27</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-mesure-100ms-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-dette-technique">📷</a></td></tr><tr><td><strong>Code inconnu non bloquant</strong><br><span class="muted">Un code inconnu propose une création rapide ou une vente en « article divers ».<br><i>Seul le message « code inconnu » existe ; prévu phase 1 par la spec.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-SALE-03</td><td></td><td></td></tr><tr><td><strong>Vente au poids</strong><br><span class="muted">Vendre au poids (kg, 3 décimales) par saisie manuelle ou code balance.<br><i>Quantités en millièmes et calcul au poids faits dans le moteur ; saisie du poids et codes balance non faits.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SALE-05, RG-SALE-07</td><td>0.x</td><td></td></tr><tr><td><strong>Mise en attente (park &amp; retrieve)</strong><br><span class="muted">Mettre un panier de côté avec une étiquette et le rappeler plus tard sur la même caisse.<br><i>Lot R2 : « Attente » au panier (étiquette « Client n » proposée, remplaçable), 20 tickets au plus par caisse, liste « Tickets en attente (n) », rappel avec échange du panier en cours, client attaché conservé, prix du catalogue en vigueur ; remises soumises à PIN à ressaisir ; purge à la clôture tracée (ParkedCartExpired, audit serveur). Android et iOS.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-50, RG-SALE-51</td><td>R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r2-vente">📷</a></td></tr><tr><td><strong>Suppression de ligne avant encaissement</strong><br><span class="muted">Retirer une ligne ou vider le panier librement, chaque suppression étant comptée pour l&#39;anti-fraude.<br><i>Retrait libre ; chaque ligne disparue au « − » et chaque panier vidé émet CartLinesRemoved (produit, quantité, montant, session, caissier), hors ligne compris ; le vidage après encaissement ne compte pas. Lu par le tableau anti-fraude (lot 3.9).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-52</td><td>1.x, 3.9</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-anti-fraude">📷</a></td></tr></tbody></table><h2 id="moteur-de-calcul" tabindex="-1">Moteur de calcul <a class="header-anchor" href="#moteur-de-calcul" aria-label="Permalink to &quot;Moteur de calcul&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Moteur de calcul partagé</strong><br><span class="muted">Montants en centimes, prix TTC, TVA arrondie par ligne (half-up), mêmes résultats JVM / iOS / Android (golden tests).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-20, RG-SALE-21, RG-SALE-22</td><td>0.x</td><td></td></tr><tr><td><strong>Revérification serveur des ventes</strong><br><span class="muted">Le serveur rejoue le moteur partagé sur chaque vente synchronisée ; un écart est signalé, jamais corrigé.<br><i>Écart signalé en ANOMALY + JET plutôt que par un statut INTEGRITY_FAILED sur la vente.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-23</td><td>1.x, 2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr></tbody></table><h2 id="remises" tabindex="-1">Remises <a class="header-anchor" href="#remises" aria-label="Permalink to &quot;Remises&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Remises ligne et ticket</strong><br><span class="muted">Remise en pourcentage ou en montant sur une ligne ou le ticket, répartie au prorata pour la TVA.<br><i>Éditeur de remise en caisse (tap sur une ligne, bouton « Remise » du panier), pourcentage ou montant, aperçu du moteur partagé ; le serveur recalcule chaque remise (lot 3.2).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-10, RG-SALE-11, RG-SALE-13</td><td>0.x, 3.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-remises">📷</a></td></tr><tr><td><strong>Remise au-delà du seuil sous PIN</strong><br><span class="muted">Au-delà des seuils du magasin, une remise exige le PIN d&#39;un manager et un motif.<br><i>Seuils et motifs dans la politique de vente publiée par l&#39;owner ; motif puis PIN manager hors ligne ; approbation portée par la vente ; anomalie serveur si une remise dépasse le seuil sans approbation valable.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-12</td><td>3.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-remises">📷</a></td></tr><tr><td><strong>Remise fidélité</strong><br><span class="muted">Racheter des points de fidélité sous forme de remise ticket.<br><i>Fait au lot 3.3 : rachat de points en caisse (palier atteint → remise), écriture de rachat tracée.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SALE-14</td><td></td><td></td></tr></tbody></table><h2 id="paiements" tabindex="-1">Paiements <a class="header-anchor" href="#paiements" aria-label="Permalink to &quot;Paiements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Espèces, carte et paiement mixte</strong><br><span class="muted">Rendu monnaie sur les espèces, carte confirmée à la main, plusieurs paiements par vente, trop-perçu non-espèces refusé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-30, RG-SALE-31, RG-SALE-32, RG-SALE-34</td><td>0.x, 1.x, UX2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-encaissement-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux2-caisse-ios">📷</a></td></tr><tr><td><strong>Mode de paiement « Autre »</strong><br><span class="muted">Encaisser par chèque, bon ou autre mode au libellé configurable.<br><i>Lot R2 : libellés publiés par l&#39;owner (politique de vente, défaut Chèque et Bon d&#39;achat), mode « Autre » de la feuille de paiement (Android et iOS), libellé scellé avec la vente (champ provider), jamais de rendu, une ligne par libellé dans les X et Z (caisse et serveur).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-30</td><td>R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r2-vente">📷</a></td></tr><tr><td><strong>Vente immuable et atomique</strong><br><span class="muted">Vente, événement et mouvements de stock écrits dans la même transaction ; numérotation sans trou survivant au crash.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-35, RG-SALE-36</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a></td></tr><tr><td><strong>Ardoise et avoir client</strong><br><span class="muted">Payer sur le crédit du client (plafond) et rembourser un retour en avoir.<br><i>Ardoise (lot 3.4) ; avoir (lot R2) : retour remboursé sur le compte du client attaché (avec ou sans ticket), solde négatif utilisable en paiement « Ardoise / avoir » même sans plafond.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-33, RG-SALE-62</td><td>R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r2-vente">📷</a></td></tr><tr><td><strong>Titre-restaurant</strong><br><span class="muted">Paiement MEAL_VOUCHER plafonné au montant éligible, solde en paiement scindé, jamais de rendu.<br><i>Livré au lot 3.13 (02/11/2026) : acceptation et plafond par magasin (25 € proposés en euros), montant éligible net des remises plafonné, tuile « Titre-resto » sur iOS et Android (téléphone, tablette, addition), paiement scindé titre + carte, jamais de rendu, revérification au push (anomalie jamais bloquante), rapport et bordereau de remise CSV au back-office. Part égale d&#39;addition au téléphone de salle : quote-part éligible portée par la part (corrigé le 08/11).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-38</td><td>3.13</td><td><a href="/VendoraSystem-docs/preuves/2026-11-02-313-titres-restaurant-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-02-313-titres-restaurant-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-02-313-titres-restaurant-web">📷</a></td></tr><tr><td><strong>Pourboires</strong><br><span class="muted">Pourboire optionnel hors CA et hors TVA, espèces ou carte, pour un salarié ou le pot commun, compté dans X / Z et rapporté au back-office.<br><i>Bénéficiaire limité au vendeur connecté ou au pot commun ; rapport « par service » = identifiant de session brut ; pas d&#39;export PDF ni de ligne dans l&#39;historique.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-39</td><td>2.9, 2.14</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-pourboires">📷</a></td></tr><tr><td><strong>Encaissement d&#39;une addition</strong><br><span class="muted">Encaisser une addition en tout, en parts égales ou par articles, à la caisse ou à la table par le téléphone de salle.<br><i>Pas de verrou si deux caisses encaissent la même addition en partition réseau ; ventilation TVA d&#39;une part égale proportionnelle (±1 centime).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-REST-21, RG-REST-22</td><td>2.7, 2.15</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-addition">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a></td></tr></tbody></table><h2 id="fournisseurs-de-paiement" tabindex="-1">Fournisseurs de paiement <a class="header-anchor" href="#fournisseurs-de-paiement" aria-label="Permalink to &quot;Fournisseurs de paiement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Fournisseur de paiement pluggable</strong><br><span class="muted">Interface PaymentProvider (initier, statut, confirmer, annuler), QR dynamique, statut suivi, repli manuel carte.<br><i>Fournisseur SIMULATED réservé au développement.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-37</td><td>2.10</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-paiement-fournisseur">📷</a></td></tr><tr><td><strong>Connecteurs configurables par magasin</strong><br><span class="muted">Flouci, Konnect, Paymee et TPE CB simulés, activés par l&#39;OWNER par magasin (identifiants chiffrés), webhooks signés.<br><i>Libellés de la page « Paiements fournisseur » figés ; rotation de la clé de chiffrement ; confirmation TERMINAL non exposée dans l&#39;UI.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-37</td><td>2.16</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-connecteurs-paiement">📷</a></td></tr><tr><td><strong>Passerelles de paiement réelles</strong><br><span class="muted">Brancher les API HTTP réelles Flouci / Konnect / Paymee, le protocole du TPE et TUNPAY.<br><i>Clés sandbox et comptes marchands = actions terrain ; TUNPAY : norme non publiée.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-SALE-37</td><td>2.16</td><td></td></tr><tr><td><strong>Rapprochement des paiements fournisseur</strong><br><span class="muted">Chaque vente payée par fournisseur est rapprochée de son intent au push (OK / anomalie) et visible au back-office.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-37</td><td>2.10, 2.14, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-paiement-fournisseur">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr></tbody></table><h2 id="ticket-impression" tabindex="-1">Ticket &amp; impression <a class="header-anchor" href="#ticket-impression" aria-label="Permalink to &quot;Ticket &amp; impression&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Ticket ESC/POS</strong><br><span class="muted">Ticket 58 / 80 mm (lignes, TVA par taux, paiements, zone fiscale, logo) via une file d&#39;impression durable jamais bloquante.<br><i>Translittération ASCII de base (code page à faire).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-41</td><td>1.x, 2.22</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-impression-stock-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-logo-config-appareil">📷</a></td></tr><tr><td><strong>États d&#39;imprimante</strong><br><span class="muted">Plus de papier / capot ouvert suspend la file sans perdre de ticket ; imprimante simulée pilotable.<br><i>Transports Bluetooth / USB à écrire ; validation sur imprimante thermique physique à faire par l&#39;utilisateur.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-HW-06</td><td>2.17</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-imprimante-simulee">📷</a></td></tr><tr><td><strong>Double numérotation des tickets</strong><br><span class="muted">Numéro local sans trou attribué hors ligne, puis numéro séquentiel de magasin attribué par le serveur.<br><i>Numéro local sans trou (hors ligne) ; numéro séquentiel de magasin attribué par le serveur à la réception (lot R2, V53), visible au back-office (ventes de la session, historique client).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-40</td><td>1.x, R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r2-vente">📷</a></td></tr><tr><td><strong>Réimpression DUPLICATA</strong><br><span class="muted">Réimprimer n&#39;importe quel ticket de la session, marqué « DUPLICATA ».<br><i>Réimpressible tant que l&#39;événement n&#39;est pas purgé ; trace d&#39;audit faite pour le Z (lot 2.23), pas pour le ticket de vente.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-SALE-43</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-migrations">📷</a></td></tr><tr><td><strong>Reçu digital par QR</strong><br><span class="muted">QR sur le ticket vers une page publique du reçu, active après la synchronisation.<br><i>Fait au lot 3.5 : QR du reçu sur le ticket, page de reçu en ligne, envoi par email avec consentement.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-SALE-42</td><td></td><td></td></tr></tbody></table><h2 id="annulations-retours" tabindex="-1">Annulations &amp; retours <a class="header-anchor" href="#annulations-retours" aria-label="Permalink to &quot;Annulations &amp; retours&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Annulation d&#39;un ticket</strong><br><span class="muted">Annuler une vente de la session ouverte sous PIN manager + motif : stock contre-passé, espèces rendues, ticket d&#39;annulation.<br><i>Pas d&#39;annulation depuis le back-office ; ticket d&#39;annulation imprimé couvert par test, non capturé.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-53</td><td>2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a></td></tr><tr><td><strong>Retour avec ticket</strong><br><span class="muted">Vente REFUND scellée aux prix d&#39;origine, quantités retournables contrôlées, remboursement au prorata, stock RETURN ou LOSS.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-60, RG-SALE-61, RG-SALE-63, RG-SALE-64</td><td>2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a></td></tr><tr><td><strong>Retour sans ticket et politique de retour</strong><br><span class="muted">Retour au prix catalogue maximum en espèces, autorisé ou non par la politique du magasin (fenêtre, mode de repli).<br><i>Remboursement en avoir : phase 3.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-62, RG-SALE-63</td><td>2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Remboursement d&#39;un paiement fournisseur</strong><br><span class="muted">La part payée via un fournisseur est remboursée chez lui avant la vente REFUND, sinon repli de la politique.<br><i>Tout ou repli (pas de remboursement ligne à ligne) ; passerelles réelles non branchées (503).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-SALE-63</td><td>2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Ticket d&#39;origine retrouvé sur le serveur</strong><br><span class="muted">Retrouver un ticket vendu sur une autre caisse (par numéro) et ses quantités encore retournables.<br><i>Listé dans les restes du lot 2.20 ; aujourd&#39;hui traité en retour sans ticket.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-SALE-61</td><td></td><td></td></tr></tbody></table><h2 id="back-office" tabindex="-1">Back-office <a class="header-anchor" href="#back-office" aria-label="Permalink to &quot;Back-office&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Consultation des ventes</strong><br><span class="muted">Consulter les ventes au back-office (période, caisse, vendeur, session), leur détail et les retours liés.<br><i>Sessions de caisse : ventes de chaque session avec numéro de magasin et numéro de ticket, paiements libellés (lot R2), rapport X serveur ; additions (page Service). Restent une liste générale filtrable des ventes et la réimpression PDF.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td></td><td>2.11, 2.23, R2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-service-back-office">📷</a></td></tr><tr><td><strong>Configuration de la vente</strong><br><span class="muted">Régler par magasin la politique de retour, les seuils de remise, les motifs, l&#39;article divers, les préfixes balance et le pied de ticket.<br><i>Politique de retour (lot 2.23), seuils et motifs de remise (lot 3.2) publiés par l&#39;owner ; article divers, préfixes balance et pied de ticket non configurables.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td>RG-SALE-12, RG-SALE-62</td><td>2.23, 3.2</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-31-remises">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Mise en attente des paniers (park &amp; retrieve).</li><li>Code inconnu : création rapide ou article divers.</li><li>Vente au poids en caisse et codes balance.</li><li>Mode de paiement « Autre » (chèque, bon).</li><li>Reçu digital par QR et page publique.</li><li>Numéro séquentiel de magasin attribué par le serveur.</li><li>Passerelles de paiement réelles (Flouci, Konnect, Paymee, TPE CB) dès les clés sandbox.</li><li>Recherche du ticket d&#39;origine sur le serveur pour les retours inter-caisses.</li><li>Liste des ventes au back-office et configuration complète de la vente.</li><li>Ardoise, avoir, remise fidélité et titre-restaurant (phase 3).</li></ul>',22)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
